import{_ as o,a0 as i,w as p,s as g,ao as r,I as t,x as n,a1 as e,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何使用 syslog-ng 从远程 Linux 机器上收集日志 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 syslog-ng 从远程 Linux 机器上收集日志 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 syslog-ng 从远程 Linux 机器上收集日志 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 syslog-ng 从远程 Linux 机器上收集日志 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180109 How to use syslog-ng to collect logs from remote Linux machines","title":"如何使用 syslog-ng 从远程 Linux 机器上收集日志","tag":"201803","desc":""},"relativePath":"201803/20180109 How to use syslog-ng to collect logs from remote Linux machines.md","filePath":"[post].md"}'),c={name:"201803/20180109 How to use syslog-ng to collect logs from remote Linux machines.md"};function d(u,s,h,y,m,b){const a=i("Link");return p(),g("div",null,[s[13]||(s[13]=r(`<h1 id="如何使用-syslog-ng-从远程-linux-机器上收集日志" tabindex="-1">如何使用 syslog-ng 从远程 Linux 机器上收集日志 <a class="header-anchor" href="#如何使用-syslog-ng-从远程-linux-机器上收集日志" aria-label="Permalink to “如何使用 syslog-ng 从远程 Linux 机器上收集日志”">​</a></h1><p>![linuxhero.jpg][1]</p><p>如果你的数据中心全是 Linux 服务器，而你就是系统管理员。那么你的其中一项工作内容就是查看服务器的日志文件。但是，如果你在大量的机器上去查看日志文件，那么意味着你需要挨个去登入到机器中来阅读日志文件。如果你管理的机器很多，仅这项工作就可以花费你一天的时间。</p><p>另外的选择是，你可以配置一台单独的 Linux 机器去收集这些日志。这将使你的每日工作更加高效。要实现这个目的，有很多的不同系统可供你选择，而 syslog-ng 就是其中之一。</p><p>syslog-ng 的不足是文档并不容易梳理。但是，我已经解决了这个问题，我可以通过这种方法马上进行安装和配置 syslog-ng。下面我将在 Ubuntu Server 16.04 上示范这两种方法：</p><ul><li>UBUNTUSERVERVM 的 IP 地址是 192.168.1.118 ，将配置为日志收集器</li><li>UBUNTUSERVERVM2 将配置为一个客户端，发送日志文件到收集器</li></ul><p>现在我们来开始安装和配置。</p><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><p>安装很简单。为了尽可能容易，我将从标准仓库安装。打开一个终端窗口，运行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install syslog-ng</span></span></code></pre></div><p>你必须在收集器和客户端的机器上都要运行上面的命令。安装完成之后，你将开始配置。</p><h3 id="配置收集器" tabindex="-1">配置收集器 <a class="header-anchor" href="#配置收集器" aria-label="Permalink to “配置收集器”">​</a></h3><p>现在，我们开始日志收集器的配置。它的配置文件是 <code>/etc/syslog-ng/syslog-ng.conf</code>。syslog-ng 安装完成时就已经包含了一个配置文件。我们不使用这个默认的配置文件，可以使用 <code>mv /etc/syslog-ng/syslog-ng.conf /etc/syslog-ng/syslog-ng.conf.BAK</code> 将这个自带的默认配置文件重命名。现在使用 <code>sudo nano /etc/syslog/syslog-ng.conf</code> 命令创建一个新的配置文件。在这个文件中添加如下的行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@version: 3.5</span></span>
<span class="line"><span>@include &quot;scl.conf&quot;</span></span>
<span class="line"><span>@include &quot;\`scl-root\`/system/tty10.conf&quot;</span></span>
<span class="line"><span>    options {</span></span>
<span class="line"><span>        time-reap(30);</span></span>
<span class="line"><span>        mark-freq(10);</span></span>
<span class="line"><span>        keep-hostname(yes);</span></span>
<span class="line"><span>        };</span></span>
<span class="line"><span>    source s_local { system(); internal(); };</span></span>
<span class="line"><span>    source s_network {</span></span>
<span class="line"><span>        syslog(transport(tcp) port(514));</span></span>
<span class="line"><span>        };</span></span>
<span class="line"><span>    destination d_local {</span></span>
<span class="line"><span>    file(&quot;/var/log/syslog-ng/messages_\${HOST}&quot;); };</span></span>
<span class="line"><span>    destination d_logs {</span></span>
<span class="line"><span>        file(</span></span>
<span class="line"><span>            &quot;/var/log/syslog-ng/logs.txt&quot;</span></span>
<span class="line"><span>            owner(&quot;root&quot;)</span></span>
<span class="line"><span>            group(&quot;root&quot;)</span></span>
<span class="line"><span>            perm(0777)</span></span>
<span class="line"><span>            ); };</span></span>
<span class="line"><span>    log { source(s_local); source(s_network); destination(d_logs); };</span></span></code></pre></div><p>需要注意的是，syslog-ng 使用 514 端口，你需要确保在你的网络上它可以被访问。</p><p>保存并关闭这个文件。上面的配置将转存期望的日志文件（由 <code>system()</code> 和 <code>internal()</code> 指出）到 <code>/var/log/syslog-ng/logs.txt</code> 中。因此，你需要使用如下的命令去创建所需的目录和文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mkdir /var/log/syslog-ng</span></span>
<span class="line"><span>sudo touch /var/log/syslog-ng/logs.txt</span></span></code></pre></div><p>使用如下的命令启动和启用 syslog-ng：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl start syslog-ng</span></span>
<span class="line"><span>sudo systemctl enable syslog-ng</span></span></code></pre></div><h3 id="配置客户端" tabindex="-1">配置客户端 <a class="header-anchor" href="#配置客户端" aria-label="Permalink to “配置客户端”">​</a></h3><p>我们将在客户端上做同样的事情（移动默认配置文件并创建新配置文件）。拷贝下列文本到新的客户端配置文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@version: 3.5</span></span>
<span class="line"><span>@include &quot;scl.conf&quot;</span></span>
<span class="line"><span>@include &quot;\`scl-root\`/system/tty10.conf&quot;</span></span>
<span class="line"><span>source s_local { system(); internal(); };</span></span>
<span class="line"><span>destination d_syslog_tcp {</span></span>
<span class="line"><span>              syslog(&quot;192.168.1.118&quot; transport(&quot;tcp&quot;) port(514)); };</span></span>
<span class="line"><span>log { source(s_local);destination(d_syslog_tcp); };</span></span></code></pre></div><p>请注意：请将 IP 地址修改为收集器的 IP 地址。</p><p>保存和关闭这个文件。与在配置为收集器的机器上一样的方法启动和启用 syslog-ng。</p><h2 id="查看日志文件" tabindex="-1">查看日志文件 <a class="header-anchor" href="#查看日志文件" aria-label="Permalink to “查看日志文件”">​</a></h2><p>回到你的配置为收集器的服务器上，运行这个命令 <code>sudo tail -f /var/log/syslog-ng/logs.txt</code>。你将看到包含了收集器和客户端的日志条目的输出（图 A）。</p><p><img src="https://tr4.cbsistatic.com/hub/i/2018/01/09/6a24e5c0-6a29-46d3-8a66-bc72747b5beb/6f94d3e6c6c2121fab6223ed9d8c6aa6/syslognga.jpg" alt="图 A"></p><p>恭喜你！syslog-ng 已经正常工作了。你现在可以登入到你的收集器上查看本地机器和远程客户端的日志了。如果你的数据中心有很多 Linux 服务器，在每台服务器上都安装上 syslog-ng 并配置它们作为客户端发送日志到收集器，这样你就不需要登入到每个机器去查看它们的日志了。</p><hr>`,29)),t("p",null,[s[1]||(s[1]=n("via: ",-1)),e(a,{href:"https://www.techrepublic.com/article/how-to-use-syslog-ng-to-collect-logs-from-remote-linux-machines/"},{default:l(()=>[...s[0]||(s[0]=[n("https://www.techrepublic.com/article/how-to-use-syslog-ng-to-collect-logs-from-remote-linux-machines/",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=n("作者：",-1)),e(a,{href:"%5B1%5D:https://tr1.cbsistatic.com/hub/i/r/2017/01/11/51204409-68e0-49b8-a637-01af26be85f6/resize/770x/688dfedad4ed30ec4baf548c2adb8cd4/linuxhero.jpg"},{default:l(()=>[...s[2]||(s[2]=[n("Jack Wallen",-1)])]),_:1}),s[6]||(s[6]=n(" 译者：",-1)),e(a,{href:"https://github.com/qhwdw"},{default:l(()=>[...s[3]||(s[3]=[n("qhwdw",-1)])]),_:1}),s[7]||(s[7]=n(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[4]||(s[4]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[8]||(s[8]=[n("LCTT",-1)])]),_:1}),s[11]||(s[11]=n(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:l(()=>[...s[9]||(s[9]=[n("Linux中国",-1)])]),_:1}),s[12]||(s[12]=n(" 荣誉推出",-1))])])}const _=o(c,[["render",d]]);export{x as __pageData,_ as default};
